#!/usr/bin/env python3
"""Impact Oracle – show the blast radius of changing a file."""
import json, sys, os
from pathlib import Path
from collections import defaultdict, deque

HOME = Path.home()
GRAPH = Path('file_graph.json')
INDEX = Path('llm_index_compact.jsonl')
FUNC_INDEX = Path('func_index.jsonl')

def load_index():
    entries = {}
    if INDEX.exists():
        with open(INDEX) as f:
            for line in f:
                e = json.loads(line)
                entries[e['p']] = e
    return entries

def load_graph():
    if not GRAPH.exists():
        return {}
    with open(GRAPH) as f:
        return json.load(f)

def get_project(file_path, entries):
    """Return project tag for a file path."""
    return entries.get(file_path, {}).get('pj', 'unknown')

def build_reverse_graph(graph):
    """Convert {src: [target, ...]} to {target: [src, ...]}."""
    reverse = defaultdict(set)
    for src, targets in graph.items():
        for tgt in targets:
            reverse[tgt].add(src)
    return reverse

def blast_radius(file_path, reverse_graph, entries, max_depth=5):
    """BFS through reverse dependencies (who imports this file)."""
    visited = set()
    queue = deque()
    queue.append((file_path, 0))
    affected = []  # list of (file, distance)
    while queue:
        current, depth = queue.popleft()
        if current in visited or depth > max_depth:
            continue
        visited.add(current)
        if current != file_path:
            affected.append((current, depth))
        for dependent in reverse_graph.get(current, []):
            if dependent not in visited:
                queue.append((dependent, depth + 1))
    return affected

def compute_score(affected, entries):
    """Score based on total direct/indirect dependents, weighted by project."""
    total = len(affected)
    # bonus for crossing project boundaries
    projects = {get_project(f, entries) for f, _ in affected}
    score = min(100, total * 5 + len(projects) * 10)
    return score, projects

# ── Main ─────────────────────────────────────────────────
if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python3 impact_oracle.py <file_path>")
        print("   Example: python3 impact_oracle.py deepcli/core.py")
        sys.exit(1)

    target_file = sys.argv[1]
    # Make relative to HOME if needed
    if os.path.isabs(target_file):
        try:
            target_file = str(Path(target_file).relative_to(HOME))
        except ValueError:
            pass

    entries = load_index()
    graph = load_graph()
    reverse_graph = build_reverse_graph(graph)

    if target_file not in entries:
        print(f"⚠️  File '{target_file}' not found in master index. Did you index it?")
        sys.exit(1)

    # Direct dependents (who imports this file)
    direct = sorted(reverse_graph.get(target_file, set()))
    print(f"📄 File: {target_file}")
    print(f"   Project: {entries[target_file].get('pj', 'unknown')} | Dependents count (used_by): {entries[target_file].get('by', 0)}")

    # Direct breakdown by project
    proj_direct = defaultdict(list)
    for f in direct:
        proj = get_project(f, entries)
        proj_direct[proj].append(f)

    print(f"\n🔗 Direct dependents ({len(direct)} files across {len(proj_direct)} projects):")
    for proj, files in sorted(proj_direct.items()):
        print(f"   [{proj}] {len(files)} files:")
        for f in files[:5]:
            print(f"      - {f}")
        if len(files) > 5:
            print(f"      ... and {len(files)-5} more")

    # Transitive blast (reverse BFS)
    affected = blast_radius(target_file, reverse_graph, entries)
    score, projects = compute_score(affected, entries)
    print(f"\n💥 Blast radius (up to 5 hops): {len(affected)} files affected across {len(projects)} projects")
    print(f"   Blast Score: {score}/100")
    # Show affected projects
    project_counts = defaultdict(int)
    for f, _ in affected:
        project_counts[get_project(f, entries)] += 1
    print("   Project impact distribution:")
    for proj, cnt in sorted(project_counts.items()):
        print(f"      {proj}: {cnt} files")

    # Show if any affected files are staged for promotion (via foresight_state.json if available)
    foresight_file = Path('foresight_state.json')
    if foresight_file.exists():
        with open(foresight_file) as fs:
            fstate = json.load(fs)
        staged = fstate.get('readiness', {}).get('scores', {})
        affected_staged = [f for f, _ in affected if f in staged]
        if affected_staged:
            print(f"\n📊 Staged/ripe files within blast radius ({len(affected_staged)}):")
            for f in affected_staged[:10]:
                score_val = staged[f]
                flag = '🍑' if score_val >= 80 else ''
                print(f"   {flag} {f} (readiness {score_val})")
            if len(affected_staged) > 10:
                print(f"   ... and {len(affected_staged)-10} more")
        else:
            print("\n✅ No staged files are in the blast radius.")
