    "echo": "🔁 Echo Reach",
    "anchor": "⚓ Anchor Count",
    "entropy": "🔥 Entropy Score",
    "convergence": "🎯 Convergence Point",
}

def load_index():
    entries = {}
    if INDEX.exists():
        with open(INDEX) as f:
            for line in f:
                e = json.loads(line)
                entries[e['p']] = e
    return entries

def load_graph():
    if not GRAPH.exists():
        return {}
    with open(GRAPH) as f:
        return json.load(f)

def get_project(file_path, entries):
    return entries.get(file_path, {}).get('pj', 'unknown')

def build_reverse_graph(graph):
    reverse = defaultdict(set)
    for src, targets in graph.items():
        for tgt in targets:
            reverse[tgt].add(src)
    return reverse

def shockwave(file_path, reverse_graph, entries, max_depth=5):
    """BFS through reverse dependencies."""
    visited = set()
    queue = deque([(file_path, 0)])
    affected = []
    while queue:
        current, depth = queue.popleft()
        if current in visited or depth > max_depth:
            continue
        visited.add(current)
        if current != file_path:
            affected.append((current, depth))
        for dependent in reverse_graph.get(current, []):
            if dependent not in visited:
                queue.append((dependent, depth + 1))
    return affected

def compute_shockwave(affected, entries):
    total = len(affected)
    projects = {get_project(f, entries) for f, _ in affected}
    score = min(100, total * 5 + len(projects) * 10)
    return score, projects

def compute_ripple(affected):
    """Distance distribution – how deep does the change propagate?"""
    depths = [d for _, d in affected]
    if not depths:
        return 0
    return round(sum(depths) / len(depths), 2)

def compute_anchor(affected):
    """How many are direct (distance 1)?"""
    return sum(1 for _, d in affected if d == 1)

